// Process and format the daily report data
const reportData = $input.first().json.data;
const summary = reportData.summary;
const details = reportData.details;

// Calculate additional metrics
const totalEvents = summary.total_events;
const criticalEvents = details.filter(event => event.severity === 'critical').reduce((sum, event) => sum + event.count, 0);
const importantEvents = details.filter(event => event.severity === 'important').reduce((sum, event) => sum + event.count, 0);

// Format report text
let reportText = `📊 Daily Summary Report\n`;
reportText += `📅 Date: ${reportData.date_range.from}\n`;
reportText += `👥 Manager Level: ${reportData.manager_level}\n`;
reportText += `📈 Total Events: ${totalEvents}\n`;
reportText += `🚨 Critical Events: ${criticalEvents}\n`;
reportText += `⚠️ Important Events: ${importantEvents}\n\n`;

if (details.length > 0) {
  reportText += `📋 Event Breakdown:\n`;
  details.forEach(event => {
    const emoji = event.severity === 'critical' ? '🚨' : '⚠️';
    reportText += `${emoji} ${event.event_type}: ${event.count}\n`;
  });
} else {
  reportText += `✅ No events recorded for this period.\n`;
}

reportText += `\n🕐 Generated at: ${reportData.generated_at}`;

// Determine if report should be sent (only if there are events)
const shouldSendReport = totalEvents > 0;

return {
  reportText: reportText,
  reportData: reportData,
  shouldSendReport: shouldSendReport,
  metrics: {
    totalEvents,
    criticalEvents,
    importantEvents
  }
};

// Format task status report for department managers
const taskData = $input.first().json.data;
const summary = taskData.summary;
const details = taskData.details;

let taskReportText = `📋 Task Status Report for Department Managers\n`;
taskReportText += `📅 Date: ${taskData.date_range.from}\n`;
taskReportText += `👥 Manager Level: ${taskData.manager_level}\n`;
taskReportText += `📊 Total Task Events: ${summary.total_task_events}\n\n`;

if (details.length > 0) {
  taskReportText += `📝 Task Activity Details:\n`;
  details.slice(0, 10).forEach(task => { // Limit to first 10 tasks
    taskReportText += `• Task #${task.entity_id}: ${task.event_type}\n`;
    if (task.after_data && task.after_data.status) {
      taskReportText += `  Status: ${task.after_data.status}\n`;
    }
    taskReportText += `  Time: ${task.occurred_at}\n\n`;
  });

  if (details.length > 10) {
    taskReportText += `... and ${details.length - 10} more tasks\n`;
  }
} else {
  taskReportText += `✅ No task activity recorded for this period.\n`;
}

return {
  taskReportText: taskReportText,
  taskData: taskData
};

// Log completion of scheduled report
const reportData = $('Format Report').first().json;
const taskData = $('Format Task Report').first().json;

return {
  message: 'Daily scheduled reports completed successfully',
  timestamp: new Date().toISOString(),
  reports_sent: {
    daily_summary: true,
    task_status: true
  },
  metrics: reportData.metrics,
  task_events: taskData.taskData.summary.total_task_events
};

// Log that no report was sent due to no events
return {
  message: 'No daily report sent - no events recorded',
  timestamp: new Date().toISOString(),
  date: $now.minus({days: 1}).toFormat('yyyy-MM-dd'),
  reason: 'No events to report'
};
